const PHRASES={en:{'I NEED HELP':'I need help','I AM IN PAIN':'I am in pain','CALL AN AMBULANCE':'Call an ambulance','CALL THE POLICE':'Call the police','I AM LOST':'I am lost','I NEED MY FAMILY':'I need my family'},zu:{'I NEED HELP':'Ngidinga usizo','I AM IN PAIN':'Ngisezinhlungwini','CALL AN AMBULANCE':'Shayela i-ambulensi','CALL THE POLICE':'Shayela amaphoyisa','I AM LOST':'Ngilahlekile','I NEED MY FAMILY':'Ngidinga umndeni wami'},ve:{'I NEED HELP':'Ndi toda thuso','I AM IN PAIN':'Ndi khou pfa vhuṱungu','CALL AN AMBULANCE':'Vhidzani ambulense','CALL THE POLICE':'Vhidzani mapholisa','I AM LOST':'Ndo xela','I NEED MY FAMILY':'Ndi toda muṱa wanga'},st:{'I NEED HELP':'Ke hloka thuso','I AM IN PAIN':'Ke bohlokong','CALL AN AMBULANCE':'Bitsa ambulense','CALL THE POLICE':'Bitsa mapolesa','I AM LOST':'Ke lahlehile','I NEED MY FAMILY':'Ke hloka lelapa la ka'},tn:{'I NEED HELP':'Ke tlhoka thuso','I AM IN PAIN':'Ke mo botlhokong','CALL AN AMBULANCE':'Bitsa ambulense','CALL THE POLICE':'Bitsa mapodisi','I AM LOST':'Ke latlhegile','I NEED MY FAMILY':'Ke tlhoka ba lelapa'},af:{'I NEED HELP':'Ek het hulp nodig','I AM IN PAIN':'Ek het pyn','CALL AN AMBULANCE':'Bel ’n ambulans','CALL THE POLICE':'Bel die polisie','I AM LOST':'Ek is verdwaal','I NEED MY FAMILY':'Ek het my familie nodig'}};
