const phraseVisuals={Hello:{emoji:'👋'},'Thank you':{emoji:'🙏'},Please:{emoji:'🤲'},Help:{emoji:'🆘'},Yes:{emoji:'👍'},No:{emoji:'👎'},'I need help':{emoji:'🆘'}};
const t=k=>T[profile.language]?.[k]??T.en[k]??k;
function localizeBackendError(message){const m=String(message||'');if(m.includes('Email already registered'))return t('emailExists');if(m.includes('Invalid email or password'))return t('invalidLogin');if(m.includes('PHP/MySQL backend not configured')||m.includes('Database service unavailable')||m.includes('Backend unavailable'))return t('offlineBlocked');if(m.includes('Please provide valid details'))return t('invalidDetails');if(m.includes('Not signed in')||m.includes('Session expired'))return t('sessionExpired');return m||t('offlineBlocked')}
function populateLanguageSelects(){['registerLanguage','languageSelect'].forEach(id=>{const el=$(id);if(!el)return;const old=el.value;el.innerHTML=Object.entries(LANGS).map(([code,name])=>`<option value="${code}">${name}</option>`).join('');el.value=LANGS[old]?old:(profile.language||'en')})}
function applyLanguage(){const lang=profile.language||'en';document.documentElement.lang=lang;populateLanguageSelects();document.querySelectorAll('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;if(T[lang]?.[key]!==undefined)el.textContent=T[lang][key]});document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{const key=el.dataset.i18nPlaceholder;if(T[lang]?.[key]!==undefined)el.placeholder=T[lang][key]});$('registerLanguage').value=lang;$('languageSelect').value=lang;renderSignPhrases();renderEmergency();renderCameraSignChips();$('greeting').textContent=profile.name?`${lang==='en'?'Hi':t('hello')}, ${profile.name.split(' ')[0]}`:t('brandName')}
function toast(msg){const tEl=$('toast');tEl.textContent=msg;tEl.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>tEl.classList.remove('show'),2800)}
function setStatus(text,good=true){$('statusText').textContent=text;$('statusDot').style.background=good?'#22c55e':'#f59e0b'}
function escapeHtml(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function showAuth(view){const auth=$('authApp');auth.classList.remove('hidden');$('mainApp').classList.add('hidden');document.querySelectorAll('.auth-view').forEach(v=>v.classList.remove('active'));$(view+'View').classList.add('active');auth.classList.toggle('auth-landing',view==='welcome');auth.classList.toggle('auth-form-page',view!=='welcome');applyLanguage()}
function showApp(user){currentUser=user;profile={name:user.name,email:user.email,language:user.language||'en',favourites:[]};localStorage.setItem(PROFILE_KEY,JSON.stringify(profile));$('authApp').classList.add('hidden');$('mainApp').classList.remove('hidden');applyLanguage();checkBackend();}
async function api(action,payload={}){const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify({action,...payload})});let d={};try{d=await r.json()}catch{}if(!r.ok||!d.success)throw new Error(d.message||'Backend unavailable');return d}
