function activateTab(tab){document.querySelectorAll('.tab-panel').forEach(p=>p.classList.toggle('active',p.id===tab));document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));document.querySelectorAll('.quick').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));closeDrawer();}
