// ---------- Camera + hand landmark AI ----------
function landmarkVector(lm){const base=lm[0];return lm.map(p=>[p.x-base.x,p.y-base.y,p.z-base.z]).flat()}
function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
function angle3(a,b,c){const ab={x:a.x-b.x,y:a.y-b.y},cb={x:c.x-b.x,y:c.y-b.y};const dot=ab.x*cb.x+ab.y*cb.y;const mag=Math.hypot(ab.x,ab.y)*Math.hypot(cb.x,cb.y);return mag?Math.acos(Math.max(-1,Math.min(1,dot/mag)))*180/Math.PI:0}
function fingerExtended(lm,mcp,pip,tip){return angle3(lm[mcp],lm[pip],lm[tip])>150&&dist(lm[tip],lm[0])>dist(lm[pip],lm[0])*1.04}
function demoPredict(lm){
  const thumb=fingerExtended(lm,2,3,4);
  const index=fingerExtended(lm,5,6,8);
  const middle=fingerExtended(lm,9,10,12);
  const ring=fingerExtended(lm,13,14,16);
  const pinky=fingerExtended(lm,17,18,20);
  const count=[thumb,index,middle,ring,pinky].filter(Boolean).length;
  if(count===5)return {label:t('openHand'),confidence:.86};
  if(count===0)return {label:t('closedHand'),confidence:.84};
  if(index&&!middle&&!ring&&!pinky)return {label:t('pointing'),confidence:.82};
  if(index&&middle&&!ring&&!pinky)return {label:t('twoFingers'),confidence:.80};
  if(thumb&&!index&&!middle&&!ring&&!pinky)return {label:t('thumbOnly'),confidence:.74};
  return {label:t('handDetected'),confidence:.62};
}
function trainingData(){try{return JSON.parse(localStorage.getItem(TRAIN_KEY)||'[]')}catch{return[]}}
function saveTraining(d){localStorage.setItem(TRAIN_KEY,JSON.stringify(d.slice(-2400)));updateVocabulary()}
function knnPredict(v){const data=trainingData();if(data.length<8)return null;const scored=data.map(x=>({label:x.label,d:Math.sqrt(x.vector.reduce((s,n,i)=>s+(n-v[i])**2,0))})).sort((a,b)=>a.d-b.d).slice(0,7);const votes={};scored.forEach(x=>votes[x.label]=(votes[x.label]||0)+1);const label=Object.entries(votes).sort((a,b)=>b[1]-a[1])[0];if(!label)return null;const best=scored.find(x=>x.label===label[0]);return {label:label[0],confidence:Math.max(.5,Math.min(.99,1-best.d/1.7))}}
function drawLandmarks(lm){overlay.width=video.videoWidth||640;overlay.height=video.videoHeight||480;ctx.clearRect(0,0,overlay.width,overlay.height);if(!lm)return;ctx.strokeStyle='#5b35d5';ctx.lineWidth=Math.max(2,overlay.width/500);const links=[[0,1],[1,2],[2,3],[3,4],[0,5],[5,6],[6,7],[7,8],[0,9],[9,10],[10,11],[11,12],[0,13],[13,14],[14,15],[15,16],[0,17],[17,18],[18,19],[19,20],[5,9],[9,13],[13,17]];links.forEach(([a,b])=>{ctx.beginPath();ctx.moveTo(lm[a].x*overlay.width,lm[a].y*overlay.height);ctx.lineTo(lm[b].x*overlay.width,lm[b].y*overlay.height);ctx.stroke()});ctx.fillStyle='#1677ff';lm.forEach(p=>{ctx.beginPath();ctx.arc(p.x*overlay.width,p.y*overlay.height,Math.max(3,overlay.width/220),0,Math.PI*2);ctx.fill()})}
function setPrediction(result){$('gesture').textContent=result.label;$('confidence').textContent=Math.round(result.confidence*100)+'%';const label=result.label;const open=t('openHand'),closed=t('closedHand'),pointing=t('pointing');$('messageOutput').textContent=label===open?t('hello'):label===closed?t('help'):label===pointing?t('point'):label}
function clearPrediction(){predictionVotes=[];$('gesture').textContent=t('noHand');$('confidence').textContent='—'}
async function initHands(){
  if(hands)return;
  if(!window.Hands)throw new Error('MediaPipe Hands script did not load.');
  hands=new Hands({locateFile:file=>`https://cdn.jsdelivr.net/npm/@mediapipe/hands/${file}`});
  hands.setOptions({maxNumHands:1,modelComplexity:0,selfieMode:false,minDetectionConfidence:.35,minTrackingConfidence:.35});
  hands.onResults(results=>{
    handFrames++;
    const lm=results.multiHandLandmarks?.[0];
    drawLandmarks(lm);
    if(!lm){
      if(cameraRunning && handFrames % 8 === 0) setStatus(t('cameraAi'),true);
      clearPrediction();
      return;
    }
    lastHandAt=Date.now();
    setStatus(t('handDetected')+' • '+Math.round((results.multiHandLandmarks?.length||1))+' hand',true);
    const vector=landmarkVector(lm);
    if(collecting){
      const label=($('trainingLabel')?.value||'').trim().toLowerCase();
      const now=Date.now();
      if(label && now-lastSampleAt>=120){
        const d=trainingData();
        d.push({label,vector,createdAt:now});
        lastSampleAt=now;
        saveTraining(d);
        updateTrainingUI();
      }
    }
    const result=knnPredict(vector)||demoPredict(lm);
    predictionVotes.push(result);
    if(predictionVotes.length>8)predictionVotes.shift();
    const counts={};predictionVotes.forEach(x=>counts[x.label]=(counts[x.label]||0)+1);
    const winner=Object.entries(counts).sort((a,b)=>b[1]-a[1])[0];
    const stable=winner&&winner[1]>=3?predictionVotes.find(x=>x.label===winner[0])||result:result;
    setPrediction(stable);
  });
}
async function loadTeachableMachineModel(url){
  const clean=(url||'').trim();
  if(!clean)return toast('Paste your Teachable Machine model URL first.');
  if(!window.tmImage)throw new Error('Teachable Machine library did not load.');
  const base=clean.endsWith('/')?clean:clean+'/';
  tmModel=await tmImage.load(base+'model.json',base+'metadata.json');
  localStorage.setItem('signbridge_tm_model_url',base);
  $('tmStatus').textContent='Custom Teachable Machine model loaded';
  toast('Custom sign model loaded.');
}
async function predictWithTM(){
  if(!tmModel||tmBusy||!cameraRunning)return false;
  const now=performance.now();if(now-lastTmAt<120)return false;lastTmAt=now;tmBusy=true;
  try{
    const predictions=await tmModel.predict(video,false);
    predictions.sort((a,b)=>b.probability-a.probability);
    const top=predictions[0];
    if(top&&top.probability>=.60){setPrediction({label:top.className,confidence:top.probability});return true}
    $('gesture').textContent=t('uncertain');$('confidence').textContent=top?Math.round(top.probability*100)+'%':'—';
    return true;
  }catch(e){console.error('tm prediction',e);return false}finally{tmBusy=false}
}
async function processCameraFrame(){
  if(!cameraRunning||!hands||processingFrame)return;
  processingFrame=true;
  try{
    if(video.readyState>=2 && video.videoWidth>0 && video.videoHeight>0){
      const used=await predictWithTM();
      if(!used){
        await hands.send({image:video});
      }
    }
  }catch(e){
    console.error('SignBridge detector frame error:',e);
    $('gesture').textContent='Detector error';
    $('confidence').textContent='—';
  }finally{
    processingFrame=false;
    if(cameraRunning) animationFrame=requestAnimationFrame(processCameraFrame);
  }
}
async function startCamera(){
  if(cameraRunning)return stopCamera();
  try{
    if(!navigator.mediaDevices?.getUserMedia)throw new Error('getUserMedia unavailable');
    stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'user'},width:{ideal:1280},height:{ideal:720}},audio:false});
    video.srcObject=stream;
    await new Promise(resolve=>video.readyState>=2?resolve():video.onloadedmetadata=resolve);
    await video.play();
    cameraRunning=true;$('cameraPlaceholder').style.display='none';$('cameraBtn').textContent=t('stop');setStatus(t('cameraOn'));toast(t('cameraOn'));
    renderCameraSignChips();
    try{
      await initHands();
      setStatus(tmModel?t('cameraTm'):t('cameraAi'),true);
      handFrames=0;lastHandAt=0;
      if(detectorTimer)clearInterval(detectorTimer);
      detectorTimer=setInterval(()=>{
        if(cameraRunning && !lastHandAt && handFrames>8){
          $('gesture').textContent=t('noHand');
          $('confidence').textContent='—';
        }
      },1500);
      animationFrame=requestAnimationFrame(processCameraFrame);
    }
    catch(e){console.error('SignBridge detector init error:',e);setStatus(t('cameraAiOffline'),false);toast(t('cameraNeedInternet'))}
  }catch(e){console.error('camera',e);let m=t('cameraUnavailable');if(e.name==='NotAllowedError')m=t('cameraPermission');if(e.name==='NotFoundError')m=t('cameraMissing');if(e.name==='NotReadableError')m=t('cameraBusy');toast(m);setStatus(t('cameraUnavailable'),false)}
}
function stopCamera(){if(animationFrame)cancelAnimationFrame(animationFrame);animationFrame=null;if(detectorTimer)clearInterval(detectorTimer);detectorTimer=null;if(stream)stream.getTracks().forEach(t=>t.stop());stream=null;video.srcObject=null;cameraRunning=false;predictionVotes=[];handFrames=0;lastHandAt=0;$('cameraBtn').textContent=t('startCamera');$('cameraPlaceholder').style.display='grid';setStatus(t('ready'));ctx.clearRect(0,0,overlay.width,overlay.height)}
$('cameraBtn').onclick=startCamera;
$('collectBtn').onclick=()=>{
  if(!cameraRunning){toast(t('startCameraFirst'));return}
  collecting=!collecting;
  lastSampleAt=0;
  updateTrainingUI();
  toast(collecting?'Training started. Hold the selected sign and move slightly.':'Training stopped.');
};

const cameraLearnKeys=['Hello','Thank you','Please','Help','Yes','No'];
const trainingTargets=['Hello','Thank you','Please','Help','Yes','No'];
const trainingTargetEmoji={Hello:'👋','Thank you':'🙏',Please:'🤲',Help:'🆘',Yes:'👍',No:'👎'};
function renderCameraSignChips(){
  const wrap=$('cameraSignChips');
  if(!wrap)return;
  const labels=phraseLabels[profile.language]||phraseLabels.en;
  wrap.innerHTML=trainingTargets.map((k,i)=>`<button type="button" class="sign-chip" data-train-sign="${escapeHtml(k)}">${trainingTargetEmoji[k]} ${escapeHtml(labels[i]||k)}</button>`).join('');
  wrap.querySelectorAll('[data-train-sign]').forEach(b=>b.onclick=()=>{
    $('trainingLabel').value=b.dataset.trainSign||'Hello';
    toast((b.dataset.trainSign||'Sign')+' selected. '+(profile.language==='en'?'Show that sign to the camera and tap Collect samples.':''));
    updateTrainingUI();
  });
}
function renderTrainingTargets(){
  const select=$('trainingLabel');
  if(!select)return;
  const labels=phraseLabels[profile.language]||phraseLabels.en;
  select.innerHTML=trainingTargets.map((k,i)=>`<option value="${escapeHtml(k)}">${trainingTargetEmoji[k]} ${escapeHtml(labels[i]||k)}</option>`).join('');
  select.onchange=updateTrainingUI;
  updateTrainingUI();
}
function updateTrainingUI(){
  const selected=$('trainingLabel')?.value||trainingTargets[0];
  const data=trainingData();
  const count=data.filter(x=>x.label===selected.toLowerCase()).length;
  const total=data.length;
  if($('trainingStatus'))$('trainingStatus').textContent=`${count} ${count===1?'sample':'samples'}`;
  if($('trainingProgressBar'))$('trainingProgressBar').style.width=Math.min(100,(count/30)*100)+'%';
  if($('collectBtn'))$('collectBtn').textContent=collecting?t('stop'):t('collectSamples');
}
function updateTrainingLabelAfterLanguage(){renderTrainingTargets();renderCameraSignChips();}


