function renderSignPhrases(){$('signPhraseChips').innerHTML=phraseKeys.map((key,i)=>`<button class="phrase-chip" type="button" data-signphrase="${escapeHtml(key)}">${escapeHtml(phraseLabels[profile.language]?.[i]||phraseLabels.en[i])}</button>`).join('');document.querySelectorAll('[data-signphrase]').forEach(b=>b.onclick=()=>{const key=b.dataset.signphrase;$('textToSignInput').value=phraseLabels[profile.language]?.[phraseKeys.indexOf(key)]||key;showTextSign(key)})}
function showTextSign(text){const clean=text.trim().toLowerCase();let idx=phraseKeys.findIndex((key,i)=>key.toLowerCase()===clean||phraseLabels[profile.language]?.[i]?.toLowerCase()===clean);if(idx<0)idx=phraseKeys.findIndex(key=>clean.includes(key.toLowerCase()));const isKnown=idx>=0;const phrase=isKnown?phraseKeys[idx]:'';const meta=isKnown?phraseVisuals[phrase]:{emoji:'💬'};$('signWord').textContent=isKnown?(phraseLabels[profile.language]?.[idx]||phrase):(text.trim()||t('whatSay'));$('signEmoji').textContent=meta.emoji;$('signInstruction').textContent=t('visualCueGeneric');activateTab('textSign');$('signSpeakBtn').dataset.text=text.trim()||$('signWord').textContent}
$('showSignBtn').onclick=()=>showTextSign($('textToSignInput').value);
$('signSpeakBtn').onclick=()=>{const text=$('signSpeakBtn').dataset.text||$('signWord').textContent;if('speechSynthesis'in window){const u=new SpeechSynthesisUtterance(text);u.lang=profile.language==='zu'?'zu-ZA':profile.language==='af'?'af-ZA':'en-ZA';speechSynthesis.speak(u)}else toast(t('speechUnavailable'))};

