$('clearBtn').onclick=()=>{$('messageOutput').textContent=t('messagePlaceholder');$('gesture').textContent=t('waiting');$('confidence').textContent='—';$('aiNote').classList.add('hidden')};
$('aiBtn').onclick=async()=>{const gesture=$('gesture').textContent;if(!gesture||gesture===t('waiting')||gesture===t('noHand'))return toast(t('showHandFirst'));$('aiNote').classList.remove('hidden');const localMap={'Hello':'Hello','Thank you':'Thank you','Please':'Please','Help':'Help','Yes':'Yes','No':'No'};const result=localMap[gesture]||gesture;$('messageOutput').textContent=result;$('aiNote').textContent='SignBridge AI: '+result;if('speechSynthesis'in window){const u=new SpeechSynthesisUtterance(result);u.lang=profile.language==='zu'?'zu-ZA':profile.language==='af'?'af-ZA':'en-ZA';speechSynthesis.speak(u)}};

