function updateVocabulary(){const d=trainingData();const count=$('sampleCount');const vocab=$('vocabulary');if(!count||!vocab)return;count.textContent=d.length;const c={};d.forEach(x=>c[x.label]=(c[x.label]||0)+1);vocab.innerHTML=Object.keys(c).length?Object.entries(c).map(([l,n])=>`<span>${escapeHtml(l)} · ${n}</span>`).join(''):`<span>${escapeHtml(t('noLocalSigns'))}</span>`}

